import{_ as t,o as a,c as n,a2 as s}from"./chunks/framework.hw3Av5Vn.js";const m=JSON.parse('{"title":"Jazz Mashup","description":"","frontmatter":{},"headers":[],"relativePath":"demos/JAZZ_MASHUP.md","filePath":"demos/JAZZ_MASHUP.md"}'),o={name:"demos/JAZZ_MASHUP.md"};function r(h,e,i,l,d,c){return a(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="jazz-mashup" tabindex="-1">Jazz Mashup <a class="header-anchor" href="#jazz-mashup" aria-label="Permalink to &quot;Jazz Mashup&quot;">​</a></h1><p>The mashups that set another work&#39;s notes on a jazz band. Each is described below, with the features it uses; <a href="./../DEMOS">About Demos</a> lists every demo.</p><ul><li><a href="#bop_invention">The Invention in A Minor as Bebop</a>: <code>bop_invention.yml</code></li><li><a href="#the_bucket">The Funeral March as a New Orleans Brass Band</a>: <code>the_bucket.yml</code></li></ul><p><a id="bop_invention"></a></p><h2 id="the-invention-in-a-minor-as-bebop-bop-invention-yml" tabindex="-1">The Invention in A Minor as Bebop: <code>bop_invention.yml</code> <a class="header-anchor" href="#the-invention-in-a-minor-as-bebop-bop-invention-yml" aria-label="Permalink to &quot;The Invention in A Minor as Bebop: `bop_invention.yml`&quot;">​</a></h2><p>Bop invention: the Two-Part Invention in A minor as bebop. The upper voice of the Invention No. 13, BWV 784 (Johann Sebastian Bach, 1723) is public domain and is played as written, its sixteenths as swung eighths at a bebop tempo, read from a transcription in the corpus; the walking bass, the piano&#39;s chords, the answers, the solos and the drums are new.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/mashups/jazz/bop_invention.yml" target="_blank" rel="noreferrer"><code>examples/mashups/jazz/bop_invention.yml</code></a> · A minor · 200 BPM · 2:55 · 14 scenes · 9 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">ties</th><th style="text-align:center;">grooves</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="the_bucket"></a></p><h2 id="the-funeral-march-as-a-new-orleans-brass-band-the-bucket-yml" tabindex="-1">The Funeral March as a New Orleans Brass Band: <code>the_bucket.yml</code> <a class="header-anchor" href="#the-funeral-march-as-a-new-orleans-brass-band-the-bucket-yml" aria-label="Permalink to &quot;The Funeral March as a New Orleans Brass Band: `the_bucket.yml`&quot;">​</a></h2><p>The bucket: the Funeral March as a New Orleans brass band&#39;s funeral. The march theme of the third movement of the Piano Sonata No. 2 (Frédéric Chopin, 1837) is public domain and is played as written at a walk, from Claude&#39;s knowledge of the score; then the band turns it into the major, which is this demo&#39;s own doing, and dances home. The sousaphone&#39;s lines, the saxophones&#39; riffs, the shouts, the solos and the parade drums are new.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/mashups/jazz/the_bucket.yml" target="_blank" rel="noreferrer"><code>examples/mashups/jazz/the_bucket.yml</code></a> · Bb major · 60 BPM · 3:05 · 13 scenes · 10 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">ties</th><th style="text-align:center;">grooves</th><th style="text-align:center;">tempo changes</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table>',13)])])}const b=t(o,[["render",r]]);export{m as __pageData,b as default};
